const unsigned char gn2_i2c_addr     =    0xac;       /* I2C Address of S5KGN2SP */
const unsigned int  gn2_addr_byte    =    2;
const unsigned int  gn2_data_byte    =    2;
static int g_fd[ISP_MAX_PIPE_NUM] = {[0 ... (ISP_MAX_PIPE_NUM - 1)] = -1};

extern ISP_SNS_STATE_S       *g_pastGN2[ISP_MAX_PIPE_NUM];
extern ISP_SNS_COMMBUS_U      g_aunGN2BusInfo[];

void gn2_linear_4K_fps60_1845M_10bit_init(VI_PIPE ViPipe);
void gn2_linear_4K_fps30_10bit_init(VI_PIPE ViPipe);
void gn2_linear_2K7_fps60_10bit_init(VI_PIPE ViPipe);
void gn2_linear_1080P_fps60_10bit_init(VI_PIPE ViPipe);

int gn2_i2c_init(VI_PIPE ViPipe)
{
    char acDevFile[16] = {0};
    AR_U8 u8DevNum;

    if (g_fd[ViPipe] >= 0){
        return AR_SUCCESS;
    }
#ifdef AR_GPIO_I2C
    int ret;

    g_fd[ViPipe] = open("/dev/gpioi2c_ex", O_RDONLY, S_IRUSR);
    if (g_fd[ViPipe] < 0){
        ISP_TRACE(AR_DBG_ERR, "Open gpioi2c_ex error!\n");
        return AR_FAILURE;
    }
#else
    int ret;

    u8DevNum =g_aunGN2BusInfo[ViPipe].s8I2cDev;
    snprintf(acDevFile, sizeof(acDevFile),  "/dev/i2c-%u", u8DevNum);
	printf("u8DevNum=%d %s",u8DevNum,acDevFile);

    g_fd[ViPipe] = open(acDevFile, O_RDWR, S_IRUSR | S_IWUSR);

    if (g_fd[ViPipe] < 0){
        ISP_TRACE(AR_DBG_ERR, "Open /dev/ar_i2c_drv-%u error!\n", u8DevNum);
        return AR_FAILURE;
    }

    ret = ioctl(g_fd[ViPipe], I2C_SLAVE_FORCE, (gn2_i2c_addr >> 1));
    if (ret < 0){
        ISP_TRACE(AR_DBG_ERR, "I2C_SLAVE_FORCE error!\n");
        close(g_fd[ViPipe]);
        g_fd[ViPipe] = -1;
        return ret;
    }
#endif
    return AR_SUCCESS;
}

int gn2_i2c_exit(VI_PIPE ViPipe)
{
    if (g_fd[ViPipe] >= 0){
        close(g_fd[ViPipe]);
        g_fd[ViPipe] = -1;
        return AR_SUCCESS;
    }
    return AR_FAILURE;
}

int gn2_read_register(VI_PIPE ViPipe, int addr)
{
    // TODO:
	int idx = 0;
    int ret;
    char buf[8];
	char data[2];
    if (gn2_addr_byte == 2){
        buf[idx] = (addr >> 8) & 0xff;
        idx++;
        buf[idx] = addr & 0xff;
        idx++;
    }else{
        buf[idx] = addr & 0xff;
        idx++;
    }
	ret = write(g_fd[ViPipe], buf, gn2_addr_byte);
    if (ret < 0){
        ISP_TRACE(AR_DBG_ERR, "I2C_WRITE error!\n");
        return AR_FAILURE;
    }
    ret = read(g_fd[ViPipe], data, gn2_data_byte);
    if (ret < 0){
        ISP_TRACE(AR_DBG_ERR, "I2C_WRITE error!\n");
        return AR_FAILURE;
    }
	uint16_t tmp = 0;
	tmp = data[1] | (data[0] << 8);
	printf("read gn2 register 0x%x: 0x%x \n", addr, tmp);
    return AR_SUCCESS;
}

int gn2_write_register(VI_PIPE ViPipe, int addr, int data)
{
    if (0 > g_fd[ViPipe]){
        return AR_SUCCESS;
    }

#ifdef AR_GPIO_I2C
    i2c_data.dev_addr = gn2_i2c_addr;
    i2c_data.reg_addr = addr;
    i2c_data.addr_byte_num = gn2_addr_byte;
    i2c_data.data = data;
    i2c_data.data_byte_num = gn2_data_byte;

    ret = ioctl(g_fd[ViPipe], GPIO_I2C_WRITE, &i2c_data);
    if (ret){
        ISP_TRACE(AR_DBG_ERR, "GPIO-I2C write faild!\n");
        return ret;
    }
#else
    int idx = 0;
    int ret;
    char buf[8];

    if (gn2_addr_byte == 2){
        buf[idx] = (addr >> 8) & 0xff;
        idx++;
        buf[idx] = addr & 0xff;
        idx++;
    }else{
        buf[idx] = addr & 0xff;
        idx++;
    }

    if (gn2_data_byte == 2){
        buf[idx] = (data >> 8) & 0xff;
        idx++;
        buf[idx] = data & 0xff;
        idx++;
    }else{
        buf[idx] = data & 0xff;
        idx++;
    }

    ret = write(g_fd[ViPipe], buf, gn2_addr_byte + gn2_data_byte);
    if (ret < 0){
        ISP_TRACE(AR_DBG_ERR, "I2C_WRITE error!\n");
        return AR_FAILURE;
    }
	//gn2_read_register(ViPipe, addr);
#endif
    return AR_SUCCESS;
}

int gn2_write_register_8bit(VI_PIPE ViPipe, int addr, int data)
{
    if(0 > g_fd[ViPipe]){
        return AR_SUCCESS;
    }

#ifdef AR_GPIO_I2C
    i2c_data.dev_addr = gn2_i2c_addr;
    i2c_data.reg_addr = addr;
    i2c_data.addr_byte_num = gn2_addr_byte;
    i2c_data.data = data;
    i2c_data.data_byte_num = 1;

    ret = ioctl(g_fd[ViPipe], GPIO_I2C_WRITE, &i2c_data);
    if(ret){
        ISP_TRACE(AR_DBG_ERR, "GPIO-I2C write faild!\n");
        return ret;
    }
#else
    int idx = 0;
    int ret;
    char buf[8];

    if (gn2_addr_byte == 2){
        buf[idx] = (addr >> 8) & 0xff;
        idx++;
        buf[idx] = addr & 0xff;
        idx++;
    }else{
        //buf[idx] = addr & 0xff;
        //idx++;
    }

    //gn2_data_byte == 1
    {
        buf[idx] = data & 0xff;
        idx++;
    }

    ret = write(g_fd[ViPipe], buf, gn2_addr_byte + 1);
    if (ret < 0){
        ISP_TRACE(AR_DBG_ERR, "I2C_WRITE error!\n");
        return AR_FAILURE;
    }
#endif
    return AR_SUCCESS;
}


static void delay_ms(int ms)
{
    usleep(ms * 1000);
}

void gn2_prog(VI_PIPE ViPipe, int *rom)
{
    int i = 0;
    while (1){
        int lookup = rom[i++];
        int addr = (lookup >> 16) & 0xFFFF;
        int data = lookup & 0xFFFF;
        if (addr == 0xFFFE){
            delay_ms(data);
        }else if (addr == 0xFFFF){
            return;
        }else{
            gn2_write_register(ViPipe, addr, data);
        }
    }
}

