#define GN2_FLIP_MIRRO	(0x0101)
int gn2_flip_off_mirro_off(VI_PIPE ViPipe)
{
    gn2_write_register(ViPipe, GN2_FLIP_MIRRO, 0x00);
    return 0;
}

int gn2_flip_on_mirro_off(VI_PIPE ViPipe)
{
    gn2_write_register(ViPipe, GN2_FLIP_MIRRO, 0x02);
    return 0;
}

int gn2_flip_off_mirro_on(VI_PIPE ViPipe)
{
    gn2_write_register(ViPipe, GN2_FLIP_MIRRO, 0x01);
    return 0;
}

int gn2_flip_on_mirro_on(VI_PIPE ViPipe)
{
    gn2_write_register(ViPipe, GN2_FLIP_MIRRO, 0x03);
    return 0;
}

#define GN2_SENSOR_4K_60FPS_LINEAR_10BIT_MODE		(1)
#define GN2_SENSOR_4K_30FPS_LINEAR_10BIT_MODE		(2)
#define GN2_SENSOR_2K7_60FPS_LINEAR_10BIT_MODE		(3)
#define GN2_SENSOR_1080P_60FPS_LINEAR_10BIT_MODE	(4)

void gn2_default_reg_init(VI_PIPE ViPipe)
{
    AR_U32 i;
    for (i = 0; i < g_pastGN2[ViPipe]->astRegsInfo[0].u32RegNum; i++){
        //printf("set reg[0x%x]: 0x%x \n", g_pastOv13b10[ViPipe]->astRegsInfo[0].astI2cData[i].u32RegAddr,  g_pastOv13b10[ViPipe]->astRegsInfo[0].astI2cData[i].u32Data);
        if (g_pastGN2[ViPipe]->astRegsInfo[0].astI2cData[i].bUpdate){
            //printf("update set reg[0x%x]: 0x%x \n", g_pastOv13b10[ViPipe]->astRegsInfo[0].astI2cData[i].u32RegAddr,  g_pastOv13b10[ViPipe]->astRegsInfo[0].astI2cData[i].u32Data);
            gn2_write_register_8bit(ViPipe, g_pastGN2[ViPipe]->astRegsInfo[0].astI2cData[i].u32RegAddr, g_pastGN2[ViPipe]->astRegsInfo[0].astI2cData[i].u32Data);
        }
    }
}

void gn2_init(VI_PIPE ViPipe)
{
    WDR_MODE_E       enWDRMode;
    AR_BOOL          bInit;
    AR_U8            u8ImgMode;

    bInit       = g_pastGN2[ViPipe]->bInit;
    enWDRMode   = g_pastGN2[ViPipe]->enWDRMode;
    u8ImgMode   = g_pastGN2[ViPipe]->u8ImgMode;

    gn2_i2c_init(ViPipe);

    /* When sensor first init, config all registers */
    if (AR_FALSE == bInit){
        if (WDR_MODE_2To1_LINE == enWDRMode){

        }else if (WDR_MODE_3To1_LINE == enWDRMode){

        }else{
            if (GN2_SENSOR_4K_60FPS_LINEAR_10BIT_MODE == u8ImgMode)
                gn2_linear_4K_fps60_1845M_10bit_init(ViPipe);
            else if(GN2_SENSOR_4K_30FPS_LINEAR_10BIT_MODE == u8ImgMode)
            	gn2_linear_4K_fps30_10bit_init(ViPipe);
			else if (GN2_SENSOR_2K7_60FPS_LINEAR_10BIT_MODE == u8ImgMode)
                gn2_linear_2K7_fps60_10bit_init(ViPipe);
			else if (GN2_SENSOR_1080P_60FPS_LINEAR_10BIT_MODE == u8ImgMode)
                gn2_linear_1080P_fps60_10bit_init(ViPipe);
        }
    }else{ /* When sensor switch mode(linear<->WDR or resolution), config different registers(if possible) */
        if (WDR_MODE_2To1_LINE == enWDRMode){

        }else if (WDR_MODE_3To1_LINE == enWDRMode){

        }else{
            if (GN2_SENSOR_4K_60FPS_LINEAR_10BIT_MODE == u8ImgMode)
                gn2_linear_4K_fps60_1845M_10bit_init(ViPipe);
            else if(GN2_SENSOR_4K_30FPS_LINEAR_10BIT_MODE == u8ImgMode)
            	gn2_linear_4K_fps30_10bit_init(ViPipe);
			else if (GN2_SENSOR_2K7_60FPS_LINEAR_10BIT_MODE == u8ImgMode)
                gn2_linear_2K7_fps60_10bit_init(ViPipe);
			else if (GN2_SENSOR_1080P_60FPS_LINEAR_10BIT_MODE == u8ImgMode)
                gn2_linear_1080P_fps60_10bit_init(ViPipe);
        }
    }

    // for (i = 0; i < g_pastOv13b10[ViPipe]->astRegsInfo[0].u32RegNum; i++)
    // {
    //     ov13b10_write_register(ViPipe, g_pastOv13b10[ViPipe]->astRegsInfo[0].astI2cData[i].u32RegAddr, g_pastOv13b10[ViPipe]->astRegsInfo[0].astI2cData[i].u32Data);
    // }

    g_pastGN2[ViPipe]->bInit = AR_TRUE;
    return ;
}

void gn2_exit(VI_PIPE ViPipe)
{
    gn2_i2c_exit(ViPipe);
    return;
}

